            amount_raw = amount_raw[1:-1].strip()

        # Clean up amount string
        amount_clean = amount_raw.replace('$', '').replace(',', '')

        try:
            amount = float(amount_clean)
            if is_negative:
                amount = -amount

            totals[category] = totals.get(category, 0.0) + amount
        except ValueError:
            continue

    return {cat: round(total, 2) for cat, total in totals.items()}
